import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.CAgiNEKA.js";const u=JSON.parse('{"title":"2026 年 5 月更新","description":"Gemini 2.5 Pro 接入、Claude 降价、企业 Key 池隔离","frontmatter":{"title":"2026 年 5 月更新","description":"Gemini 2.5 Pro 接入、Claude 降价、企业 Key 池隔离","date":"2026-05-10T00:00:00.000Z"},"headers":[],"relativePath":"changelog/2026-05.md","filePath":"changelog/2026-05.md","lastUpdated":1778841837000}'),i={name:"changelog/2026-05.md"};function l(n,a,d,h,s,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_2026-年-5-月更新日志" tabindex="-1">2026 年 5 月更新日志 <a class="header-anchor" href="#_2026-年-5-月更新日志" aria-label="Permalink to &quot;2026 年 5 月更新日志&quot;">​</a></h1><h2 id="🆕-新上线" tabindex="-1">🆕 新上线 <a class="header-anchor" href="#🆕-新上线" aria-label="Permalink to &quot;🆕 新上线&quot;">​</a></h2><h3 id="gemini-2-5-pro-正式接入-2026-05-10" tabindex="-1">Gemini 2.5 Pro 正式接入（2026-05-10） <a class="header-anchor" href="#gemini-2-5-pro-正式接入-2026-05-10" aria-label="Permalink to &quot;Gemini 2.5 Pro 正式接入（2026-05-10）&quot;">​</a></h3><p>Google Gemini 2.5 Pro 现已在熊猫算力上线，支持：</p><ul><li><strong>100 万 token</strong> 超长上下文窗口</li><li>原生多模态（文本、图片、视频、音频）</li><li>模型 ID：<code>gemini-2.5-pro</code></li></ul><p>定价与 Google 官方保持一致，详见 <a href="/docs/models/">模型总览</a>。</p><hr><h2 id="💰-价格调整" tabindex="-1">💰 价格调整 <a class="header-anchor" href="#💰-价格调整" aria-label="Permalink to &quot;💰 价格调整&quot;">​</a></h2><h3 id="claude-3-5-系列全线降价-20-2026-05-08" tabindex="-1">Claude 3.5 系列全线降价 20%（2026-05-08） <a class="header-anchor" href="#claude-3-5-系列全线降价-20-2026-05-08" aria-label="Permalink to &quot;Claude 3.5 系列全线降价 20%（2026-05-08）&quot;">​</a></h3><p>随 Anthropic 官方同步降价，以下模型即日起生效：</p><table tabindex="0"><thead><tr><th>模型</th><th>调整前（输入/输出 per 1M）</th><th>调整后</th></tr></thead><tbody><tr><td>claude-sonnet-4-6</td><td>¥26 / ¥130</td><td><strong>¥21 / ¥105</strong></td></tr><tr><td>claude-haiku-4-5</td><td>¥0.65 / ¥3.25</td><td><strong>¥0.5 / ¥2.5</strong></td></tr></tbody></table><p>已充值余额按新价格计费，无需任何操作。</p><hr><h2 id="✨-新功能" tabindex="-1">✨ 新功能 <a class="header-anchor" href="#✨-新功能" aria-label="Permalink to &quot;✨ 新功能&quot;">​</a></h2><h3 id="企业版-独立-key-池隔离-2026-04-25" tabindex="-1">企业版：独立 Key 池隔离（2026-04-25） <a class="header-anchor" href="#企业版-独立-key-池隔离-2026-04-25" aria-label="Permalink to &quot;企业版：独立 Key 池隔离（2026-04-25）&quot;">​</a></h3><p>企业版账号现支持在主账号下创建多个「子项目」，实现：</p><ul><li>API Key 完全隔离，子项目间无法互用</li><li>独立的 RPM/TPM 限速配置</li><li>分项目的用量报表与账单</li><li>预算告警（触达阈值后自动发邮件通知）</li></ul><p>配置入口：控制台 → 项目管理 → 新建子项目</p><hr><h2 id="🔧-问题修复" tabindex="-1">🔧 问题修复 <a class="header-anchor" href="#🔧-问题修复" aria-label="Permalink to &quot;🔧 问题修复&quot;">​</a></h2><h3 id="修复-streaming-高并发下偶发断流-2026-04-18" tabindex="-1">修复 Streaming 高并发下偶发断流（2026-04-18） <a class="header-anchor" href="#修复-streaming-高并发下偶发断流-2026-04-18" aria-label="Permalink to &quot;修复 Streaming 高并发下偶发断流（2026-04-18）&quot;">​</a></h3><p><strong>现象</strong>：在高并发场景下（&gt;100 并发连接），少量 SSE 连接会在中途被强制断开，客户端收到不完整响应。</p><p><strong>原因</strong>：网关层的 keep-alive 超时设置过短，与上游连接池的配置不匹配。</p><p><strong>修复</strong>：调整网关超时配置，并增加了连接健康检测机制。修复后内部压测未复现该问题。</p><hr><p><em>查看 <a href="/docs/changelog/">完整更新日志</a> | 有问题请通过右下角按钮联系我们</em></p>',26)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
